package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Owned payload admitted unchanged on Salesforce with key API65 and caller API60.
func TestRunMapCustomHashCollisions(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"65.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2Key.cls"), "public class GladeB2Key {\n    public String value;\n    public GladeB2Key(String value) { this.value = value; }\n    public Boolean equals(Object other) { return other instanceof GladeB2Key && value == ((GladeB2Key)other).value; }\n    public Integer hashCode() { return 7; }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2Key.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>65.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2MapTest.cls"), "@IsTest private class GladeB2MapTest {\n    @IsTest static void unequalCollisionsRetainValues() {\n        GladeB2Key first = new GladeB2Key('first'); GladeB2Key second = new GladeB2Key('second');\n        System.assertEquals(false, first.equals(second));\n        Map<GladeB2Key, String> records = new Map<GladeB2Key, String>();\n        records.put(first, 'FIRST'); records.put(second, 'SECOND');\n        System.assertEquals(2, records.size());\n        System.assertEquals('FIRST', records.get(first));\n        System.assertEquals('SECOND', records.get(second));\n    }\n    @IsTest static void equalReplacementReturnsOldValue() {\n        Map<GladeB2Key, String> records = new Map<GladeB2Key, String>();\n        records.put(new GladeB2Key('first'), 'FIRST');\n        records.put(new GladeB2Key('second'), 'SECOND');\n        String old = records.put(new GladeB2Key('first'), 'REPLACED');\n        System.assertEquals('FIRST', old); System.assertEquals(2, records.size());\n        System.assertEquals('REPLACED', records.get(new GladeB2Key('first')));\n        System.assertEquals('SECOND', records.get(new GladeB2Key('second')));\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2MapTest.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>60.0</apiVersion><status>Active</status></ApexClass>\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 {
		data, _ := json.Marshal(run)
		t.Fatalf("collision cases failed: %s", data)
	}
}

// Exact owned lifecycle payload admitted with key API65 and caller API60.
func TestRunMapCollisionCollectionPaths(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"65.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2Key.cls"), "public class GladeB2Key {\n    public String value;\n    public GladeB2Key(String value) { this.value = value; }\n    public Boolean equals(Object other) { return other instanceof GladeB2Key && value == ((GladeB2Key)other).value; }\n    public Integer hashCode() { return 7; }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2Key.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>65.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2MapLifecycleTest.cls"), "@IsTest private class GladeB2MapLifecycleTest {\n    @IsTest static void literalCopyAndMissingKey() {\n        Map<GladeB2Key,String> original = new Map<GladeB2Key,String>{new GladeB2Key('first')=>'FIRST',new GladeB2Key('second')=>'SECOND'};\n        Map<GladeB2Key,String> copy = new Map<GladeB2Key,String>(original);\n        System.assertEquals(2, copy.size());\n        System.assertEquals('FIRST', copy.get(new GladeB2Key('first')));\n        System.assertEquals('SECOND', copy.get(new GladeB2Key('second')));\n        System.assertEquals(false, copy.containsKey(new GladeB2Key('missing')));\n        System.assertEquals(null, copy.get(new GladeB2Key('missing')));\n        copy.put(new GladeB2Key('first'), 'COPY');\n        System.assertEquals('FIRST', original.get(new GladeB2Key('first')));\n    }\n    @IsTest static void removalLeavesCollisionAndReinsertion() {\n        Map<GladeB2Key,String> records = new Map<GladeB2Key,String>();\n        records.put(new GladeB2Key('first'), 'FIRST');\n        records.put(new GladeB2Key('second'), 'SECOND');\n        System.assertEquals(null, records.remove(new GladeB2Key('missing')));\n        System.assertEquals('FIRST', records.get(new GladeB2Key('first')));\n        System.assertEquals(true, records.containsKey(new GladeB2Key('first')));\n        System.assertEquals('FIRST', records.remove(new GladeB2Key('first')));\n        System.assertEquals(false, records.containsKey(new GladeB2Key('first')));\n        System.assertEquals('SECOND', records.get(new GladeB2Key('second')));\n        System.assertEquals('SECOND', records.put(new GladeB2Key('second'), 'REPLACED'));\n        System.assertEquals(null, records.put(new GladeB2Key('third'), 'THIRD'));\n        System.assertEquals(2, records.size());\n        System.assertEquals('REPLACED', records.get(new GladeB2Key('second')));\n        System.assertEquals('THIRD', records.get(new GladeB2Key('third')));\n    }\n    @IsTest static void putAllRetainsSharedAlias() {\n        Map<GladeB2Key,String> records = new Map<GladeB2Key,String>();\n        records.put(new GladeB2Key('first'), 'FIRST');\n        Map<GladeB2Key,String> alias = records;\n        records.putAll(new Map<GladeB2Key,String>{new GladeB2Key('second')=>'SECOND'});\n        System.assertEquals(2, alias.size());\n        System.assertEquals('FIRST', alias.get(new GladeB2Key('first')));\n        System.assertEquals('SECOND', alias.get(new GladeB2Key('second')));\n        alias.put(new GladeB2Key('first'), 'FROM ALIAS');\n        System.assertEquals('FROM ALIAS', records.get(new GladeB2Key('first')));\n    }\n    @IsTest static void equalEntriesIgnoreInsertionOrder() {\n        Map<GladeB2Key,String> first = new Map<GladeB2Key,String>{new GladeB2Key('first')=>'FIRST',new GladeB2Key('second')=>'SECOND'};\n        Map<GladeB2Key,String> reversed = new Map<GladeB2Key,String>{new GladeB2Key('second')=>'SECOND',new GladeB2Key('first')=>'FIRST'};\n        System.assertEquals(true, first == reversed);\n        System.assertEquals(true, reversed == first);\n        System.assertEquals(first, reversed);\n    }\n    @IsTest static void differentKeysRemainUnequalWithSameValues() {\n        Map<GladeB2Key,String> first = new Map<GladeB2Key,String>{new GladeB2Key('first')=>'VALUE',new GladeB2Key('second')=>'VALUE'};\n        Map<GladeB2Key,String> different = new Map<GladeB2Key,String>{new GladeB2Key('third')=>'VALUE',new GladeB2Key('fourth')=>'VALUE'};\n        System.assertEquals(false, first == different);\n        System.assertEquals(false, different == first);\n        System.assertNotEquals(first, different);\n    }\n    @IsTest static void stringRenderingContainsBothEntries() {\n        Map<GladeB2Key,String> records = new Map<GladeB2Key,String>{new GladeB2Key('first')=>'FIRST',new GladeB2Key('second')=>'SECOND'};\n        String rendered = String.valueOf(records);\n        System.assertEquals(true, rendered.contains('first'), rendered);\n        System.assertEquals(true, rendered.contains('second'), rendered);\n        System.assertEquals(true, rendered.contains('FIRST'), rendered);\n        System.assertEquals(true, rendered.contains('SECOND'), rendered);\n    }\n    @IsTest static void nestedStringRenderingContainsBothEntries() {\n        Map<GladeB2Key,String> records = new Map<GladeB2Key,String>{new GladeB2Key('first')=>'FIRST',new GladeB2Key('second')=>'SECOND'};\n        Map<String,Object> envelope = new Map<String,Object>{'records'=>records};\n        String rendered = String.valueOf(envelope);\n        System.assertEquals(true, rendered.contains('records'), rendered);\n        System.assertEquals(true, rendered.contains('first'), rendered);\n        System.assertEquals(true, rendered.contains('second'), rendered);\n        System.assertEquals(true, rendered.contains('FIRST'), rendered);\n        System.assertEquals(true, rendered.contains('SECOND'), rendered);\n    }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeB2MapLifecycleTest.cls-meta.xml"), "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>60.0</apiVersion><status>Active</status></ApexClass>\n")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 7 || got.Passed != 7 {
		data, _ := json.Marshal(run)
		t.Fatalf("collection paths failed: %s", data)
	}
}
